16	/// Tela 4 — Meus Registros, spec-4-1's real build: every `Entry`,
17	/// newest-first, grouped by day, each card marked by origin. Replaces the
18	/// former `MeusRegistrosPlaceholderScreen`.
19	///
20	/// [cubit] is a DI `lazySingleton` (Code Map) — this `StatefulWidget` never
21	/// closes it (`BlocProvider.value`, same convention
22	/// `AccountSettingsScreen` already uses for its own singleton cubit); only
23	/// this screen's own [ScrollController] is this `State`'s to dispose.
24	///
25	/// The global `ExpiryOverlayHost` shows its "Sessão expirada" dialog via
26	/// `showGeneralDialog` on the `Navigator` *above* this screen's own widget
27	/// subtree (`expiry_overlay_host.dart`) — this screen is never popped or
28	/// rebuilt from scratch underneath it, so [_scrollController]'s position
29	/// and [cubit]'s state survive that overlay appearing with no extra code
30	/// needed here (Acceptance Criteria's third bullet).
31	class MeusRegistrosScreen extends StatefulWidget {
32	  const MeusRegistrosScreen({required this.cubit, super.key});
33	
34	  final MeusRegistrosCubit cubit;
35	
36	  @override
37	  State<MeusRegistrosScreen> createState() => _MeusRegistrosScreenState();
38	}
39	
40	class _MeusRegistrosScreenState extends State<MeusRegistrosScreen> {
41	  // RNF01: no loading UI below 300ms — same threshold/`Timer` pattern as
42	  // `BootSplashScreen`.
43	  static const _skeletonThreshold = Duration(milliseconds: 300);
44	
45	  final ScrollController _scrollController = ScrollController();
46	  Timer? _skeletonTimer;
47	  bool _showSkeleton = false;
48	
49	  @override
50	  void initState() {
51	    super.initState();
52	    widget.cubit.loadFirstPage();
53	    _skeletonTimer = Timer(_skeletonThreshold, () {
54	      if (mounted) {
55	        setState(() => _showSkeleton = true);
56	      }
57	    });
58	    _scrollController.addListener(_onScroll);
59	  }
60	
61	  @override
62	  void dispose() {
63	    _skeletonTimer?.cancel();
64	    _scrollController
65	      ..removeListener(_onScroll)
66	      ..dispose();
67	    super.dispose();
68	  }
69	
70	  void _onScroll() {
71	    if (!_scrollController.hasClients) {
72	      return;
73	    }
74	    final position = _scrollController.position;
75	    // Pre-fetches a little before the exact end (reusing `spacing2xl`
76	    // purely as a scroll-distance buffer, not a new literal) for a
77	    // smoother scroll-pagination feel; `loadMore()` itself is a no-op once
78	    // there's no further page or a call is already in flight.
79	    if (position.pixels >= position.maxScrollExtent - DesignTokens.spacing2xl) {
80	      widget.cubit.loadMore();
81	    }
82	  }
83	
84	  @override
85	  Widget build(BuildContext context) {
86	    return BlocProvider.value(
87	      value: widget.cubit,
88	      child: Scaffold(
89	        backgroundColor: DesignTokens.colorSurfaceBg,
90	        body: Column(
91	          children: [
92	            const BackArrowHeader(title: 'Meus Registros'),
93	            Expanded(
94	              child: BlocBuilder<MeusRegistrosCubit, MeusRegistrosState>(
95	                builder: (context, state) => switch (state) {
96	                  MeusRegistrosLoading() =>
97	                    _showSkeleton
98	                        ? const _SkeletonList()
99	                        : const SizedBox.shrink(),
100	                  MeusRegistrosEmpty() => const _EmptyState(),
101	                  MeusRegistrosError(message: final message) => _ErrorState(
102	                    message: message,
103	                    onRetry: widget.cubit.loadFirstPage,
104	                  ),
105	                  MeusRegistrosLoaded() => _EntryList(
106	                    state: state,
107	                    scrollController: _scrollController,
108	                    onRetryLoadMore: widget.cubit.retryLoadMore,
109	                    onRetryTap: (entry) => widget.cubit.retry(entry.id),
110	                  ),
111	                },
112	              ),
113	            ),
114	          ],
115	        ),
116	      ),
117	    );
118	  }
119	}
