131	      padding: DesignTokens.screenPadding,
132	      itemCount: _placeholderCount,
133	      itemBuilder: (context, index) => Padding(
134	        padding: const EdgeInsets.only(bottom: DesignTokens.spacingSm),
135	        child: const EntrySkeletonCard(),
136	      ),
137	    );
138	  }
139	}
