197	class _EntryList extends StatelessWidget {
198	  const _EntryList({
199	    required this.state,
200	    required this.scrollController,
201	    required this.onRetryLoadMore,
202	    required this.onRetryTap,
203	  });
204	
205	  final MeusRegistrosLoaded state;
206	  final ScrollController scrollController;
207	  final VoidCallback onRetryLoadMore;
208	  final void Function(Entry entry) onRetryTap;
209	
210	  @override
211	  Widget build(BuildContext context) {
212	    final groups = state.groups;
213	    // A non-empty `state.entries` can still yield zero groups if every one
214	    // of its `occurredAt` values is malformed (`groupEntriesByDate()` skips
215	    // rather than throws) — fall back to the same plain empty-state text
216	    // rather than rendering a ListView with nothing visibly in it.
217	    if (groups.isEmpty) {
218	      return const _EmptyState();
219	    }
220	    return ListView.builder(
221	      controller: scrollController,
222	      padding: DesignTokens.screenPadding,
223	      itemCount: groups.length + 1,
224	      itemBuilder: (context, index) {
225	        if (index == groups.length) {
226	          return _LoadMoreFooter(
227	            hasMore: state.nextCursor != null,
228	            isLoading: state.isLoadingMore,
229	            failed: state.loadMoreFailed,
230	            onRetry: onRetryLoadMore,
231	          );
232	        }
233	        return _DateGroupSection(
234	          group: groups[index],
235	          badgeFor: state.badgeFor,
236	          onRetryTap: onRetryTap,
237	        );
238	      },
239	    );
240	  }
241	}
