243	class _DateGroupSection extends StatelessWidget {
244	  const _DateGroupSection({
245	    required this.group,
246	    required this.badgeFor,
247	    required this.onRetryTap,
248	  });
249	
250	  final EntryDateGroup group;
251	
252	  /// `MeusRegistrosLoaded.badgeFor` — the one call site outside the
253	  /// cubit/state itself (Never: "any screen recomputing badge state
254	  /// inline").
255	  final SyncBadgeState Function(Entry entry) badgeFor;
256	
257	  /// `MeusRegistrosCubit.retry`, pre-bound to this entry's own id —
258	  /// `EntryRecordCard`/`SyncBadge` only ever call this for a retryable
259	  /// error badge.
260	  final void Function(Entry entry) onRetryTap;
261	
262	  @override
263	  Widget build(BuildContext context) {
264	    return Padding(
265	      padding: const EdgeInsets.only(bottom: DesignTokens.spacingMd),
266	      child: Column(
267	        crossAxisAlignment: CrossAxisAlignment.start,
268	        children: [
269	          Text(
270	            _dayLabel(group.date),
271	            style: DesignTokens.textTitleSm.copyWith(
272	              color: DesignTokens.colorTextPrimary,
273	            ),
274	          ),
275	          const SizedBox(height: DesignTokens.spacingSm),
276	          for (final entry in group.entries) ...[
277	            EntryRecordCard(
278	              key: ValueKey(entry.id),
279	              entry: entry,
280	              badgeState: badgeFor(entry),
281	              onRetryTap: () => onRetryTap(entry),
282	            ),
283	            const SizedBox(height: DesignTokens.spacingSm),
284	          ],
285	        ],
286	      ),
287	    );
288	  }
289	}
