291	class _LoadMoreFooter extends StatelessWidget {
292	  const _LoadMoreFooter({
293	    required this.hasMore,
294	    required this.isLoading,
295	    required this.failed,
296	    required this.onRetry,
297	  });
298	
299	  final bool hasMore;
300	  final bool isLoading;
301	  final bool failed;
302	  final VoidCallback onRetry;
303	
304	  @override
305	  Widget build(BuildContext context) {
306	    if (failed) {
307	      return Padding(
308	        padding: const EdgeInsets.symmetric(vertical: DesignTokens.spacingMd),
309	        child: Center(
310	          child: TextButton(
311	            onPressed: onRetry,
312	            child: Text(
313	              'Tentar novamente',
314	              style: DesignTokens.textLabelMd.copyWith(
315	                color: DesignTokens.colorPrimary,
316	              ),
317	            ),
318	          ),
319	        ),
320	      );
321	    }
322	    if (isLoading) {
323	      return const Padding(
324	        padding: EdgeInsets.symmetric(vertical: DesignTokens.spacingMd),
325	        child: Center(
326	          child: CircularProgressIndicator(color: DesignTokens.colorPrimary),
327	        ),
328	      );
329	    }
330	    return const SizedBox.shrink();
331	  }
332	}
