334	/// "Hoje"/"Ontem"/`dd/mm/yyyy` — presentation's own job (Code Map: day
335	/// labels aren't the pure `groupEntriesByDate()`'s concern). [date] is
336	/// always already truncated to local midnight (`EntryDateGroup`'s own
337	/// contract).
338	String _dayLabel(DateTime date) {
339	  final now = DateTime.now();
340	  final today = DateTime(now.year, now.month, now.day);
341	  final yesterday = today.subtract(const Duration(days: 1));
342	  if (date == today) {
343	    return 'Hoje';
344	  }
345	  if (date == yesterday) {
346	    return 'Ontem';
347	  }
348	  final day = date.day.toString().padLeft(2, '0');
349	  final month = date.month.toString().padLeft(2, '0');
350	  return '$day/$month/${date.year}';
351	}
