1	import '../../domain/entities/entry.dart';
2	import '../../domain/entities/entry_date_group.dart';
3	import '../../domain/entities/pending_entry_write.dart';
4	import '../../domain/entities/sync_badge_state.dart';
5	
6	/// `MeusRegistrosScreen`'s own sealed state — never the shared
7	/// `Resource<T>` (Boundaries, mirrors `capture`'s `TextEntryState`
8	/// sealed-class convention, `resource.dart`'s own doc already excludes
9	/// RF07 the same way): this screen's shape — a first load, a grouped list
10	/// with its own pagination sub-state, an empty result, or a terminal
11	/// error — doesn't fit that single-fetch lifecycle.
12	sealed class MeusRegistrosState {
13	  const MeusRegistrosState();
14	}
15	
16	/// The first page is in flight — `MeusRegistrosScreen` shows a skeleton
17	/// for this only past the shared 300ms threshold (RNF01), mirroring
18	/// `BootSplashScreen`'s own `Timer` pattern; blank below it.
19	class MeusRegistrosLoading extends MeusRegistrosState {
20	  const MeusRegistrosLoading();
21	}
22	
23	/// The first page resolved with zero entries (Boundaries: "Zero entries ->
24	/// Plain 'no entries yet' text", no polished CTA — that's story 4.3).
25	class MeusRegistrosEmpty extends MeusRegistrosState {
26	  const MeusRegistrosEmpty();
27	}
28	
29	/// The first load failed with a `Failure` the repository's own
30	/// offline/Hive fallback never absorbs (e.g. `Failure.authExpired`) —
31	/// [message] is `Failure.message` verbatim, same convention
32	/// `TextEntryError.message` already uses.
33	class MeusRegistrosError extends MeusRegistrosState {
34	  const MeusRegistrosError({required this.message});
35	
36	  final String message;
37	
38	  @override
39	  bool operator ==(Object other) =>
40	      identical(this, other) ||
41	      (other is MeusRegistrosError && other.message == message);
42	
43	  @override
44	  int get hashCode => message.hashCode;
45	
46	  @override
47	  String toString() => 'MeusRegistrosError(message: $message)';
48	}
49	
50	/// A resolved page — [entries] accumulates every page fetched so far
51	/// (first load plus every successful [MeusRegistrosCubit.loadMore]),
52	/// already de-duplicated by id. [groups] re-derives the grouped view via
53	/// the pure `groupEntriesByDate()` on every read rather than this state
54	/// storing a separately-maintained, pre-grouped copy that `loadMore` would
55	/// otherwise have to keep in sync by hand.
56	class MeusRegistrosLoaded extends MeusRegistrosState {
57	  const MeusRegistrosLoaded({
58	    required this.entries,
59	    required this.nextCursor,
60	    this.isLoadingMore = false,
61	    this.loadMoreFailed = false,
62	    this.pendingWrites = const [],
63	  });
64	
65	  final List<Entry> entries;
66	
67	  /// `null` once the server's `meta.nextCursor` says there's no further
68	  /// page — also always `null` for a page served from the offline Hive
69	  /// fallback (Boundaries).
70	  final String? nextCursor;
71	
72	  /// `true` for the duration of one in-flight `loadMore()` call —
73	  /// `MeusRegistrosScreen`'s list footer shows a small spinner for this,
74	  /// distinct from the first load's full-screen skeleton.
75	  final bool isLoadingMore;
76	
77	  /// `true` after a `loadMore()` attempt fails — I/O matrix: "keeps
78	  /// current items + inline retry". [entries] is left exactly as it was;
79	  /// only the footer switches to a retry affordance.
80	  final bool loadMoreFailed;
81	
82	  /// spec-4-2 — every write `PendingEntryWriteTracker` currently holds
83	  /// (in flight or failed), mirrored from its own `pendingWrites` stream
84	  /// by `MeusRegistrosCubit`. Never contains a write that's already
85	  /// confirmed — that one has already moved into [entries] instead
86	  /// (`MeusRegistrosCubit._onEntryConfirmed`).
87	  final List<PendingEntryWrite> pendingWrites;
88	
89	  /// [entries] with each [pendingWrites] member rendered as its own
90	  /// placeholder [Entry] (content/source/[mediaDurationSeconds] from the
91	  /// pending write itself; `occurredAt` = [PendingEntryWrite.startedAt]),
92	  /// prepended ahead of [entries] — Boundaries: "Card appears top-of-
93	  /// today... before server responds". Grouping this combined list by day
94	  /// (via the same [groupEntriesByDate] every confirmed entry already
95	  /// uses) naturally lands a pending write's own card at the top of
96	  /// "Hoje", with no separate rendering path needed in the screen itself.
97	  ///
98	  /// [pendingWrites] itself holds insertion order (oldest-started first,
99	  /// `PendingEntryWriteTrackerImpl`'s own `Map` — Review finding, round 2):
100	  /// reversed here so two writes pending at once still land newest-first,
101	  /// matching [groupEntriesByDate]'s documented "callers always pass
102	  /// entries already newest-first" contract.
103	  List<Entry> get _displayEntries => [
104	    for (final pending in pendingWrites.reversed) _placeholderEntryFor(pending),
105	    ...entries,
106	  ];
107	
108	  List<EntryDateGroup> get groups => groupEntriesByDate(_displayEntries);
109	
110	  /// [entry]'s own badge (Code Map/Never: the one call site for
111	  /// `deriveSyncBadgeState()` outside its own unit tests). [entry] is
112	  /// looked up against [pendingWrites] by id — a placeholder [Entry]
113	  /// built by [_displayEntries] always has [PendingEntryWrite.tempId] as
114	  /// its [Entry.id], so this matches it back to its own pending write; a
115	  /// genuinely confirmed [Entry] from [entries] never matches one (the
116	  /// tracker's own `create()`/`retry()` already remove a pending record
117	  /// before `MeusRegistrosCubit` ever prepends the matching confirmed
118	  /// entry, so the two can never coexist here).
119	  SyncBadgeState badgeFor(Entry entry) {
120	    for (final pending in pendingWrites) {
121	      if (pending.tempId == entry.id) {
122	        return deriveSyncBadgeState(null, pending);
123	      }
124	    }
125	    return deriveSyncBadgeState(entry, null);
126	  }
127	
128	  MeusRegistrosLoaded copyWith({
129	    List<Entry>? entries,
130	    String? nextCursor,
131	    bool? isLoadingMore,
132	    bool? loadMoreFailed,
133	    List<PendingEntryWrite>? pendingWrites,
134	  }) {
135	    return MeusRegistrosLoaded(
136	      entries: entries ?? this.entries,
137	      nextCursor: nextCursor ?? this.nextCursor,
138	      isLoadingMore: isLoadingMore ?? this.isLoadingMore,
139	      loadMoreFailed: loadMoreFailed ?? this.loadMoreFailed,
140	      pendingWrites: pendingWrites ?? this.pendingWrites,
141	    );
142	  }
143	
144	  @override
145	  bool operator ==(Object other) =>
146	      identical(this, other) ||
147	      (other is MeusRegistrosLoaded &&
148	          other.nextCursor == nextCursor &&
149	          other.isLoadingMore == isLoadingMore &&
150	          other.loadMoreFailed == loadMoreFailed &&
151	          _listEquals(other.entries, entries) &&
152	          _listEquals(other.pendingWrites, pendingWrites));
153	
154	  @override
155	  int get hashCode => Object.hash(
156	    Object.hashAll(entries),
157	    nextCursor,
158	    isLoadingMore,
159	    loadMoreFailed,
160	    Object.hashAll(pendingWrites),
161	  );
162	
163	  @override
164	  String toString() =>
165	      'MeusRegistrosLoaded(entries: ${entries.length}, nextCursor: '
166	      '$nextCursor, isLoadingMore: $isLoadingMore, loadMoreFailed: '
167	      '$loadMoreFailed, pendingWrites: ${pendingWrites.length})';
168	}
169	
170	Entry _placeholderEntryFor(PendingEntryWrite pending) {
171	  final startedAtIso = pending.startedAt.toIso8601String();
172	  return Entry(
173	    id: pending.tempId,
174	    content: pending.content,
175	    source: pending.source,
176	    chatMessageId: null,
177	    occurredAt: startedAtIso,
178	    serverRevision: 0,
179	    createdAt: startedAtIso,
180	    updatedAt: startedAtIso,
181	    mediaDurationSeconds: pending.mediaDurationSeconds,
182	  );
183	}
184	
185	bool _listEquals<T>(List<T> a, List<T> b) {
186	  if (a.length != b.length) {
187	    return false;
188	  }
189	  for (var i = 0; i < a.length; i++) {
190	    if (a[i] != b[i]) {
191	      return false;
192	    }
193	  }
194	  return true;
195	}
