64	/// A plain (non-mocktail) fake — queues one `list()` result per call, same
65	/// rationale as `meus_registros_cubit_test.dart`'s own fake, plus an
66	/// optional [firstCallGate] so a test can hold the very first `list()`
67	/// call unresolved to observe the skeleton's 300ms threshold.
68	class _FakeEntriesRepository implements EntriesRepository {
69	  final List<Either<Failure, EntriesPage>> _listResults = [];
70	  int listCallCount = 0;
71	  Completer<void>? firstCallGate;
72	
73	  void queueList(Either<Failure, EntriesPage> result) {
74	    _listResults.add(result);
75	  }
76	
77	  @override
78	  Future<Either<Failure, Entry>> create({
79	    required String content,
80	    required EntrySource source,
81	    int? mediaDurationSeconds,
82	  }) async => throw UnimplementedError('not expected to be called');
83	
84	  @override
85	  Future<Either<Failure, EntriesPage>> list({
86	    String? cursor,
87	    int limit = 20,
88	  }) async {
89	    listCallCount++;
90	    if (listCallCount == 1 && firstCallGate != null) {
91	      await firstCallGate!.future;
92	    }
93	    if (_listResults.isEmpty) {
94	      throw StateError('no queued list() result for call #$listCallCount');
95	    }
96	    return _listResults.removeAt(0);
97	  }
98	}
