126	/// A controllable `PendingEntryWriteTracker` fake — unlike the trivial one
127	/// above (whose streams never emit), this one lets a test drive
128	/// [pendingWrites] directly and records every [retry] call, so a test can
129	/// assert the real screen's own tap-to-retry wiring
130	/// (`meus_registros_screen.dart`'s `onRetryTap: (entry) =>
131	/// widget.cubit.retry(entry.id)`) actually reaches the tracker with the
132	/// right `tempId` — Review finding (round 2): this exact chain (screen tap
133	/// -> cubit.retry(entry.id) -> tracker.retry(tempId)) had no end-to-end
134	/// coverage before; every other link in it was only ever exercised in
135	/// isolation (`entry_record_card_test.dart`, `meus_registros_cubit_test.
136	/// dart`).
137	class _ControllablePendingEntryWriteTracker
138	    implements PendingEntryWriteTracker {
139	  final _pendingController =
140	      StreamController<List<PendingEntryWrite>>.broadcast();
141	  final List<String> retryCalls = [];
142	
143	  void emitPendingWrites(List<PendingEntryWrite> writes) =>
144	      _pendingController.add(writes);
145	
146	  @override
147	  Stream<List<PendingEntryWrite>> get pendingWrites =>
148	      _pendingController.stream;
149	
150	  @override
151	  Stream<({String tempId, Entry entry})> get confirmedWrites =>
152	      const Stream.empty();
153	
154	  @override
155	  Future<Either<Failure, Entry>> create({
156	    required String content,
157	    required EntrySource source,
158	    int? mediaDurationSeconds,
159	  }) async => throw UnimplementedError('not expected to be called');
160	
161	  @override
162	  Future<void> retry(String tempId) async {
163	    retryCalls.add(tempId);
164	  }
165	
166	  @override
167	  Future<void> dispose() async {
168	    await _pendingController.close();
169	  }
170	}
